SELECT Id, Name FROM Product2
WHERE Id IN ('01tWt000006hV6jIAE','01tWt000006hVQ5IAM')
   OR Name IN ('CircuitMaster Analyzer','VeriSim Express','DesignEdge Pro','AI DesignShift','CircuitAI Innovator','OptiEnergy Suite','PowerPro Optimize','Workflow Genius');

SELECT oi.Id, oi.OrderId, oi.Product2Id
FROM OrderItem oi
WHERE oi.OrderId IN (
  SELECT DISTINCT OrderId FROM OrderItem WHERE Product2Id = '01tWt000006hVJdIAM'
);

SELECT id, priority, subject, description, status, contactid, accountid, ownerid, createddate, closeddate, issueid__c, orderitemid__c
FROM "Case"
WHERE id = '500Wt00000DDyznIAD';

SELECT id, priority, subject, description, status, contactid, accountid, ownerid, createddate, closeddate, issueid__c, orderitemid__c
FROM "Case"
WHERE id = '#500Wt00000DDyznIAD';

SELECT name, gmap_id, "MISC", state, num_of_reviews
FROM business_description
LIMIT 3;

SELECT track_id, SUM(revenue_usd) AS total_revenue_usd, SUM(units_sold) AS total_units
FROM sales
GROUP BY track_id;

SELECT "Index", "Date", "CloseUSD"
FROM index_trade
ORDER BY "Index", "Date";

SELECT COUNT(*) AS total_reviews, SUM(rating) AS total_rating, AVG(rating) AS overall_avg_rating
FROM review
WHERE business_ref IN ('businessref_52','businessref_84','businessref_76','businessref_87','businessref_65','businessref_94','businessref_90','businessref_16');

SELECT COUNT(DISTINCT business_ref) AS n_businesses_2018
FROM review
WHERE date >= '2018-01-01' AND date < '2019-01-01';

SELECT DISTINCT business_ref
FROM review
WHERE date >= '2018-01-01' AND date < '2019-01-01';

SELECT COUNT(*) AS n_reviews, AVG(rating) AS avg_rating, SUM(rating) AS sum_rating
FROM review
WHERE business_ref IN ('businessid_89','businessid_97','businessid_67','businessid_77','businessid_86','businessid_40','businessid_44','businessid_82');

SELECT COUNT(*) AS n_reviews, ROUND(AVG(rating),4) AS avg_rating
FROM review
WHERE business_ref IN ('businessref_89','businessref_97','businessref_67','businessref_77','businessref_86','businessref_40','businessref_44','businessref_82');

SELECT MIN(date) AS min_date, MAX(date) AS max_date, COUNT(*) AS total,
       COUNT(*) FILTER (WHERE date >= '2016-01-01' AND date < '2016-07-01') AS in_window
FROM review;

SELECT COUNT(*) AS total,
SUM(CASE WHEN Licenses LIKE '%"MIT"%' THEN 1 ELSE 0 END) AS mit_cnt
FROM packageinfo WHERE System='NPM';

SELECT (SELECT COUNT(*) FROM project_packageversion WHERE System='NPM') AS ppv_npm,
       (SELECT COUNT(*) FROM project_packageversion) AS ppv_total,
       (SELECT COUNT(*) FROM project_info) AS info_total;

SELECT Name, Version, RelationType, RelationProvenance FROM project_packageversion
WHERE ProjectName IN ('mui-org/material-ui','moment/moment','lodash/lodash','semantic-org/semantic-ui','react-native-elements/react-native-elements')
LIMIT 40;

SELECT COUNT(*) AS total_rows, COUNT(DISTINCT repo_name) AS distinct_repos,
SUM(CASE WHEN language_description LIKE '%Python%' THEN 1 ELSE 0 END) AS python_repos
FROM languages;

SELECT sample_repo_name, sample_path, content
FROM contents
WHERE sample_path ILIKE 'readme.md' OR sample_path ILIKE '%/readme.md';

SELECT id, title, summary, faq_answer__c
FROM knowledge__kav
WHERE title ILIKE '%installation%timeline%' OR title ILIKE '%volume-based%';

SELECT Id, Status, CompanySignedDate, CustomerSignedDate FROM Contract
WHERE Id IN ('800Wt00000DE9FFIA1','800Wt00000DE8sgIAD','800Wt00000DE9ryIAD')
   OR Id IN ('#800Wt00000DE9FFIA1','#800Wt00000DE8sgIAD','#800Wt00000DE9ryIAD');

SELECT "Index", Date, Open, High, Low, Close
FROM index_trade
WHERE "Index" IN ('N225','NSEI','HSI','000001.SS','399001.SZ','TWII');

SELECT "Index", "Date", "Open", "Close" FROM index_trade
WHERE "Index" IN ('IXIC','NYA','GSPTSE') AND "Date" LIKE '%2018%'
ORDER BY "Index";

SELECT "Symbol", "Company Description", "Financial Status" FROM stockinfo
WHERE "Listing Exchange" = 'Q' AND "Financial Status" IS NOT NULL AND "Financial Status" <> 'N'
ORDER BY "Symbol";

SELECT AVG(rating) AS avg_rating, COUNT(*) AS num_reviews
FROM review
WHERE business_ref IN ('businessid_10','businessid_11','businessid_24','businessid_30','businessid_4','businessid_46','businessid_47','businessid_64','businessid_96');
